// The same authored material supplies the classroom sequence and complete reading.
// The booking examples and short checks are teacher-written. E086–E097 retain
// their original question-paper, insert and marking-scheme provenance.
const ids = (requirement, ...numbers) => numbers.map(number => `S11.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows, title) => ({ headers, rows, ...(title ? { title } : {}) });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const recall = (title, body) => ({ title, body });
const specimen = (title, ...items) => ({ title, items });
const check = (prompt, answer) => ({ prompt, answer });

