        unitKeys: ['S11-PROCEDURE-CALL'], objectiveIds: ids(6, 1, 2, 3), prerequisites: ['program-booking-supplied-interface'],
        question: 'Does writing a procedure definition immediately print its receipt?',
        observe: 'The desk wants the same heading before different booking outputs. Define that action once, then decide exactly where to call it.',
