        question: 'How can AddSeats change the main program’s running total?',
        observe: 'The caller has Total 5 and a new request Seats 3. The procedure needs a copy of the request quantity but access to the original total location.',
        stimulus: { title: 'Call AddSeats(Seats, Total)', table: table(['Parameter', 'Mode', 'Meaning'], [['Quantity', 'BYVAL', 'Copy the request value 3'], ['RunningTotal', 'BYREF', 'Refer to caller Total, currently 5']]) },
